CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY);
CREATE TABLE organizations(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE tenants(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL);
CREATE TABLE memberships(tenant_id uuid REFERENCES tenants(id), user_id uuid REFERENCES users(id), role text NOT NULL CHECK(role IN ('admin','operator','viewer','approver')), PRIMARY KEY(tenant_id,user_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts(identity_hash text PRIMARY KEY, failures integer NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE enrollments(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), token_hash text UNIQUE NOT NULL, name text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE hosts(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, token_hash text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE policies(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), host_id uuid, body jsonb NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,host_id) REFERENCES hosts(tenant_id,id));
CREATE UNIQUE INDEX tenant_policy ON policies(tenant_id) WHERE host_id IS NULL;
CREATE UNIQUE INDEX host_policy ON policies(tenant_id,host_id) WHERE host_id IS NOT NULL;
CREATE TABLE snapshots(id uuid NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id), host_id uuid NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,id), UNIQUE(tenant_id,host_id,id), FOREIGN KEY(tenant_id,host_id) REFERENCES hosts(tenant_id,id));
CREATE TABLE restores(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), host_id uuid NOT NULL, snapshot_id uuid NOT NULL, body jsonb NOT NULL, status text NOT NULL CHECK(status IN ('pending','approved','denied','expired','executing','succeeded','failed')), decided_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, FOREIGN KEY(tenant_id,host_id,snapshot_id) REFERENCES snapshots(tenant_id,host_id,id));
CREATE TABLE alerts(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), host_id uuid NOT NULL, dedupe_key text NOT NULL, body jsonb NOT NULL, occurrences integer NOT NULL DEFAULT 1, acknowledged_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,host_id,dedupe_key), FOREIGN KEY(tenant_id,host_id) REFERENCES hosts(tenant_id,id));
CREATE TABLE evidence(id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), host_id uuid NOT NULL, snapshot_id uuid NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,host_id,snapshot_id) REFERENCES snapshots(tenant_id,host_id,id));
CREATE TABLE audit(id bigserial PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), actor text NOT NULL, action text NOT NULL, resource_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX snapshots_timeline ON snapshots(tenant_id,created_at DESC);
CREATE INDEX restores_queue ON restores(tenant_id,host_id,status);
CREATE INDEX audit_timeline ON audit(tenant_id,created_at DESC);
